// ==UserScript==
// @name         大冯老师的央视频下载助手
// @namespace    fmg-cctvdown
// @version      1.6.0
// @description  在 tv.cctv.com 视频页注入下载面板：自动探测真实画质档位，「直接下载 MP4」采用内联 mux.js 在浏览器内转封装；验证码改为腾讯云 COS 存储桶远程下发（随机无规律、可随时轮换）。
// @author       数智化教学大冯老师 (fmg)
// @match        https://tv.cctv.com/*/*.shtml*
// @match        https://tv.cctv.com/**/*.shtml
// @icon         https://tv.cctv.com/favicon.ico
// @grant        GM_xmlhttpRequest
// @grant        GM_setClipboard
// @grant        GM_addStyle
// @connect      vdn.apps.cntv.cn
// @connect      *.cntv.cn
// @connect      *.cntv.com
// @connect      newcntv.qcloudcdn.com
// @connect      dhls.cntv.qcloudcdn.com
// @connect      dhls.cntv.kcdnvip.com
// @connect      hls.cntv.lxdns.com
// @connect      hls.cntv.myalicdn.com
// @connect      *.qcloudcdn.com
// @connect      *.kcdnvip.com
// @connect      *.lxdns.com
// @connect      *.myalicdn.com
// @connect      *.alicdn.com
// @connect      fmg-ysp-1259190918.cos.ap-nanjing.myqcloud.com
// @connect      *.myqcloud.com
// @connect      cdn.jsdelivr.net
// @connect      unpkg.com
// @connect      cdnjs.cloudflare.com
// @connect      cdn.bootcdn.net
// @connect      registry.npmmirror.com
// @run-at       document-idle
// @license      MIT
// ==/UserScript==

// ===== 内联 mux.js 7.1.0（Apache-2.0）=======
// 以下常量是一段经 base64 编码的 mux.js 7.1.0 发行版代码。
// 运行时通过 data: URI 注入到页面上下文，不依赖任何外部 CDN。
const MUX_JS_B64 = "";

// ===== 公众号二维码（内联）====================================================
const QR_CODE_DATA_URI = "data:image/jpeg;base64,";

// ===== 验证码池（腾讯云 COS 远程下发）=====================================
// 扫码关注「数智化教学大冯老师」后，发送「央下载」，公众号会随机回复 5 个验证码之一。
//
// 这 5 个码由 rotate_codes.py 用密码学随机数生成（8 位大写字母+数字，剔除 0/O/1/I/L
// 等易混淆字符），彼此毫无规律，生成后上传到腾讯云 COS 存储桶：
//     fmg-ysp-1259190918（ap-nanjing）/ codes.json
// 脚本运行时远程拉取校验。好处有二：
//   ① 码是随机串，看不出任何递增/枚举规律；
//   ② 以后换码无需改脚本、无需重新分发 —— 重跑一次 rotate_codes.py，全网立即生效。
//
// 公众号后台的 5 条自动回复，请填成本地 codes.json 里的那 5 个码。
const COS_CODES_URL =
  'https://fmg-ysp-1259190918.cos.ap-nanjing.myqcloud.com/codes.json';
// 备用地址（可选）：如果给桶配了自定义 CDN 域名，或另建了镜像桶，填在这里，主地址失败时自动兜底
const COS_CODES_BACKUP = '';
// 应急离线码（可选）：极端断网又急需使用时可临时填几个，平时留空即可
const OFFLINE_FALLBACK_CODES = [];

const VERIFY_STORAGE_KEY = '__fmg_cctv_verify_passed__';
// 缓存键带桶标识：换桶换码后旧缓存自动失效，不会把上一批码带过来
const VERIFY_CACHE_KEY = '__fmg_cctv_verify_cache_ysp__';

// 归一化：转大写、去掉空格与分隔符，避免用户复制粘贴时带进杂质
function normCode(s) {
  return String(s || '').toUpperCase().replace(/[\s\-_]/g, '');
}

// 从 COS 拉取验证码；失败时依次回退：本地缓存 → 应急离线码
async function loadRemoteCodes() {
  let cached = [];
  try {
    const raw = localStorage.getItem(VERIFY_CACHE_KEY);
    if (raw) {
      const obj = JSON.parse(atob(raw));
      if (obj && Array.isArray(obj.codes)) cached = obj.codes.map(normCode);
    }
  } catch (e) { /* ignore */ }

  const urls = [COS_CODES_URL, COS_CODES_BACKUP].filter(Boolean);
  for (const u of urls) {
    try {
      const r = await new Promise((resolve, reject) => {
        GM_xmlhttpRequest({
          method: 'GET',
          url: u + (u.indexOf('?') >= 0 ? '&' : '?') + '_t=' + Date.now(),
          headers: { Accept: 'application/json' },
          timeout: 12000,
          onload: resolve,
          onerror: (e) => reject(new Error(e.error || 'network error')),
          ontimeout: () => reject(new Error('timeout')),
        });
      });
      if (r.status !== 200) continue;
      const data = JSON.parse(r.responseText);
      const list = (data && data.codes) || [];
      if (!list.length) continue;
      const codes = list.map(normCode).filter(Boolean);
      try {
        localStorage.setItem(
          VERIFY_CACHE_KEY,
          btoa(JSON.stringify({ codes: codes, ts: Date.now() }))
        );
      } catch (e) { /* ignore */ }
      return { codes: codes, source: 'remote' };
    } catch (e) { /* 换下一个地址 */ }
  }

  if (cached.length) return { codes: cached, source: 'cache' };
  if (OFFLINE_FALLBACK_CODES.length) {
    return { codes: OFFLINE_FALLBACK_CODES.map(normCode), source: 'offline' };
  }
  return { codes: [], source: 'fail' };
}




async function initCctvDownloader() {
  'use strict';

  // ===== 1. 取页面里的 guid =====================================================
  function getGuid() {
    const html = document.documentElement.outerHTML;
    let m = html.match(/var\s+guid\s*=\s*["']([0-9a-fA-F]{16,64})["']/);
    if (m) return m[1];
    m = html.match(/["']([0-9a-f]{32})["']/);
    return m ? m[1] : null;
  }

  // ===== 2. GM_xmlhttpRequest 的 Promise 封装 ===================================
  function gmFetch(url, opts = {}) {
    return new Promise((resolve, reject) => {
      GM_xmlhttpRequest({
        method: opts.method || 'GET',
        url,
        headers: opts.headers || {},
        responseType: opts.responseType || 'text',
        timeout: opts.timeout || 25000,
        onload: (r) => {
          if (r.status >= 200 && r.status < 300) resolve(r);
          else reject(new Error('HTTP ' + r.status));
        },
        onerror: (e) => reject(new Error(e.error || 'network error')),
        ontimeout: () => reject(new Error('timeout')),
      });
    });
  }

  const UA =
    'Mozilla/5.0 (iPhone; CPU iPhone OS 16_0 like Mac OS X) AppleWebKit/605.1.15 Mobile/15E148 Safari/604.1';
  const BASE_HEADERS = {
    'User-Agent': UA,
    Referer: 'https://tv.cctv.com/',
    Accept: '*/*',
  };

  // ===== 3. 拿视频元数据 ========================================================
  async function fetchInfo(guid) {
    const api = `https://vdn.apps.cntv.cn/api/getHttpVideoInfo.do?pid=${guid}&idl=32&idlr=32&modifyed=false`;
    const r = await gmFetch(api, { headers: BASE_HEADERS });
    return JSON.parse(r.responseText);
  }

  // ===== 4. 探测码率档位 ========================================================
  async function probeStreams(info) {
    const probes = [
      { kbps: 2000, label: '2000 kbps', res: '1280x720 (号称)' },
      { kbps: 1200, label: '1200 kbps', res: '960x540  (号称)' },
      { kbps: 850,  label: '850  kbps', res: '640x360  (真原始流)' },
      { kbps: 450,  label: '450  kbps', res: '480x270  (兜底)' },
    ];

    const hlsMain = info.hls_url || '';
    const m = hlsMain.match(
      /^(https?:\/\/[^/]+\/asp\/hls\/)main(\/.+?)\/main\.m3u8/
    );
    if (!m) return null;
    const base = m[1];
    const tail = m[2];

    const out = [];
    for (const p of probes) {
      const url = `${base}${p.kbps}${tail}/${p.kbps}.m3u8`;
      try {
        const r = await gmFetch(url, {
          headers: BASE_HEADERS,
          timeout: 15000,
        });
        if (r.status !== 200) {
          out.push({ ...p, url, ok: false, reason: 'HTTP ' + r.status });
          continue;
        }
        const txt = r.responseText || '';
        const segs = txt.split('\n').filter((l) => l.trim() && !l.startsWith('#'));
        if (!segs.length) {
          out.push({ ...p, url, ok: false, reason: '空清单' });
          continue;
        }
        const seg0 = `${base}${p.kbps}${tail}/${segs[0]}`;
        const sr = await gmFetch(seg0, {
          headers: BASE_HEADERS,
          timeout: 25000,
          responseType: 'arraybuffer',
        });
        const size = sr.response ? sr.response.byteLength : (sr.responseText || '').length;
        out.push({
          ...p,
          url,
          ok: true,
          segments: segs.length,
          seg0Bytes: size,
          real: size >= 800_000,
        });
      } catch (e) {
        out.push({ ...p, url, ok: false, reason: e.message });
      }
    }
    return out;
  }

  // ===== 5. 生成 PowerShell 一键命令 ===========================================
  function buildFfCmd(stream, title) {
    const safeTitle = title.replace(/[\\/:*?"<>|]/g, '_').trim() || 'video';
    const lines = [
      '# 央视频下载 — ' + title,
      '# 码率: ' + stream.label,
      '# 复制下面整段到 PowerShell 7+ (Windows 11 内置 5.1 也可) 运行',
      '# 要求: 已安装 ffmpeg 并加入系统 PATH (choco install ffmpeg / scoop install ffmpeg)',
      '',
      '$ErrorActionPreference = "Stop"',
      '$m3u8 = "' + stream.url + '"',
      '$out   = "' + safeTitle + '.mp4"',
      '',
      '# ffmpeg 内置 HLS demuxer: 并发拉 ts + PCR 续接 + 不重编码',
      'ffmpeg -y `',
      '  -headers "Referer: https://tv.cctv.com/" `',
      '  -user_agent "' + UA + '" `',
      '  -allowed_extensions ALL `',
      '  -protocol_whitelist "file,crypto,data,http,https,tcp,tls" `',
      '  -i "$m3u8" `',
      '  -c copy -bsf:a aac_adtstoasc -movflags +faststart `',
      '  "$out"',
      '',
      'Write-Host "完成: $out" -ForegroundColor Green',
    ];
    return lines.join('\n');
  }

  // 生成可下载的 PowerShell 一键脚本
  function buildPs1(stream, title) {
    const safeTitle = title.replace(/[\\/:*?"<>|]/g, '_').trim() || 'video';
    return [
      '# 央视频下载一键脚本 — ' + title,
      '# 码率: ' + stream.label,
      '# 右键「使用 PowerShell 运行」或在 PowerShell 中运行：',
      '#   powershell -ExecutionPolicy Bypass -File "' + safeTitle + '.ps1"',
      '',
      '$ErrorActionPreference = "Stop"',
      '',
      '$ffmpeg = Get-Command ffmpeg -ErrorAction SilentlyContinue',
      'if (-not $ffmpeg) {',
      '    Write-Host "未检测到 ffmpeg，请先安装并加入系统 PATH" -ForegroundColor Red',
      '    Write-Host "下载地址: https://ffmpeg.org/download.html" -ForegroundColor Yellow',
      '    pause',
      '    exit 1',
      '}',
      '',
      '$m3u8 = "' + stream.url + '"',
      '$out = "' + safeTitle + '.mp4"',
      '$ua = "' + UA + '"',
      '',
      'Write-Host "正在下载: $out" -ForegroundColor Cyan',
      'ffmpeg -y `',
      '  -headers "Referer: https://tv.cctv.com/" `',
      '  -user_agent "$ua" `',
      '  -allowed_extensions ALL `',
      '  -protocol_whitelist "file,crypto,data,http,https,tcp,tls" `',
      '  -i "$m3u8" `',
      '  -c copy -bsf:a aac_adtstoasc -movflags +faststart `',
      '  "$out"',
      '',
      'if ($LASTEXITCODE -eq 0) {',
      '    Write-Host "完成: $out" -ForegroundColor Green',
      '} else {',
      '    Write-Host "下载失败，请检查网络或 ffmpeg 输出" -ForegroundColor Red',
      '}',
      'pause',
      '',
    ].join('\r\n');
  }

  // ===== 6. mux.js 加载（内联，无需 CDN）==========
  function loadMuxJs() {
    return new Promise((resolve, reject) => {
      // 优先使用页面真实 window（Tampermonkey 沙箱中的 window 可能是包装对象）
      const w = typeof unsafeWindow !== 'undefined' ? unsafeWindow : window;
      if (w.muxjs && w.muxjs.mp4 && w.muxjs.mp4.Transmuxer) {
        resolve(w.muxjs);
        return;
      }

      try {
        // 屏蔽 UMD 的 CommonJS/AMD 分支，强制挂载到传入的 window 对象
        const code = atob(MUX_JS_B64);
        const wrapped =
          'var exports=undefined,module=undefined,define=undefined,globalThis=this,self=this;' +
          code;
        const fn = new Function(wrapped);
        fn.call(w);

        if (w.muxjs && w.muxjs.mp4 && w.muxjs.mp4.Transmuxer) {
          resolve(w.muxjs);
        } else {
          reject(new Error('mux.js 初始化失败：组件未挂载到 window.muxjs'));
        }
      } catch (e) {
        reject(new Error('mux.js 注入失败：' + e.message));
      }
    });
  }

  // 脚本加载成功后立即预初始化 mux.js，避免点击按钮时才初始化失败
  loadMuxJs().catch(() => {});

  // ===== 7. 浏览器内下载 MP4（mux.js 转封装 TS→fMP4）============
  function downloadPs1(stream, title) {
    const ps1 = buildPs1(stream, title);
    const encoder = new TextEncoder();
    downloadBlob(
      encoder.encode(ps1).buffer,
      `${title.replace(/[\\/:*?"<>|]/g, '_')}_${stream.kbps}.ps1`
    );
  }

  async function downloadMp4(stream, title, setStatus, setProgress) {
    const muxjs = await loadMuxJs();

    // 拉取 m3u8 清单
    const listR = await gmFetch(stream.url, { headers: BASE_HEADERS });
    const segNames = listR.responseText
      .split('\n')
      .map((l) => l.trim())
      .filter((l) => l && !l.startsWith('#'));
    if (!segNames.length) throw new Error('m3u8 没有可分片');

    const m3u8Base = stream.url.substring(0, stream.url.lastIndexOf('/') + 1);
    const estMB = (segNames.length * stream.seg0Bytes) / 1024 / 1024;
    if (estMB > 300) {
      const go = confirm(
        `预计浏览器内下载约 ${estMB.toFixed(
          0
        )}MB 数据，长视频容易内存不足或卡顿。建议优先使用「下载一键脚本(.ps1)」本地运行。\n\n是否仍要浏览器内直接下载 MP4？`
      );
      if (!go) throw new Error('用户取消浏览器内下载');
    }

    const transmuxer = new muxjs.mp4.Transmuxer({ remux: true });
    const chunks = [];
    let first = true;
    let hadError = null;

    transmuxer.on('data', (segment) => {
      if (!segment) return;
      if (first && segment.initSegment) {
        chunks.push(segment.initSegment);
        first = false;
      }
      chunks.push(segment.data || segment);
    });
    transmuxer.on('error', (err) => {
      hadError = err;
    });

    for (let i = 0; i < segNames.length; i++) {
      if (hadError) throw hadError;
      const segUrl = segNames[i].startsWith('http')
        ? segNames[i]
        : m3u8Base + segNames[i];
      setStatus(`正在下载并转封装第 ${i + 1}/${segNames.length} 段...`);
      const r = await gmFetch(segUrl, {
        headers: BASE_HEADERS,
        responseType: 'arraybuffer',
      });
      transmuxer.push(new Uint8Array(r.response));
      setProgress((i + 1) / segNames.length * 0.9);
    }

    setStatus('正在收尾...');
    await new Promise((resolve) => {
      transmuxer.on('done', resolve);
      transmuxer.flush();
      setTimeout(resolve, 5000); // fallback timeout
    });

    if (hadError) throw hadError;
    if (!chunks.length) throw new Error('转封装未输出数据');

    setStatus('正在合并 MP4...');
    let total = 0;
    chunks.forEach((c) => (total += c.byteLength));
    const final = new Uint8Array(total);
    let off = 0;
    chunks.forEach((c) => {
      final.set(c, off);
      off += c.byteLength;
    });

    const filename = `${title.replace(/[\\/:*?"<>|]/g, '_')}_${stream.kbps}.mp4`;
    downloadBlob(final.buffer, filename);
    setStatus('MP4 下载已开始');
    setProgress(1);
  }

  // ===== 8. UI 注入 ============================================================
  if (!/\.shtml/.test(location.pathname)) return;

  GM_addStyle(`
    #fmg-cctv-panel {
      position: fixed; right: 16px; bottom: 16px; z-index: 999999;
      width: 420px; max-height: 82vh; overflow: auto;
      background: #1e1e1e; color: #f0f0f0;
      font: 13px/1.5 -apple-system, "Segoe UI", "Microsoft YaHei", sans-serif;
      border: 1px solid #444; border-radius: 10px;
      box-shadow: 0 6px 20px rgba(0,0,0,.4);
      padding: 12px 14px;
    }
    #fmg-cctv-panel h3 { margin: 0 0 6px; font-size: 14px; color: #ffeb3b; }
    #fmg-cctv-panel .meta { color: #aaa; font-size: 12px; margin-bottom: 8px; }
    #fmg-cctv-panel .row { padding: 6px 0; border-top: 1px solid #333; }
    #fmg-cctv-panel .row:first-of-type { border-top: 0; }
    #fmg-cctv-panel .kbps { font-weight: bold; color: #fff; }
    #fmg-cctv-panel .badge { display: inline-block; padding: 1px 6px;
      border-radius: 3px; font-size: 11px; margin-left: 4px; }
    #fmg-cctv-panel .real   { background: #2e7d32; color: #fff; }
    #fmg-cctv-panel .fake   { background: #c62828; color: #fff; }
    #fmg-cctv-panel .err    { background: #555; color: #fff; }
    #fmg-cctv-panel .seg    { color: #888; font-size: 11px; margin-left: 6px; }
    #fmg-cctv-panel .btns { margin-top: 4px; }
    #fmg-cctv-panel button {
      cursor: pointer; padding: 3px 8px; margin-right: 4px; margin-top: 4px;
      background: #444; color: #eee; border: 0; border-radius: 4px;
      font-size: 12px;
    }
    #fmg-cctv-panel button:hover { background: #666; }
    #fmg-cctv-panel button.dlmp4 { background: #2e7d32; color: #fff; font-weight: bold; }
    #fmg-cctv-panel button.dlmp4:hover { background: #388e3c; }
    #fmg-cctv-panel button.ps1 { background: #1565c0; color: #fff; }
    #fmg-cctv-panel button.ps1:hover { background: #1976d2; }
    #fmg-cctv-panel .close {
      float: right; background: transparent; color: #888;
      font-size: 16px; padding: 0 6px;
    }
    #fmg-cctv-panel .close:hover { color: #fff; background: transparent; }
    #fmg-cctv-panel pre {
      max-height: 260px; overflow: auto; background: #111;
      padding: 6px 8px; border-radius: 4px; font-size: 11px;
      white-space: pre-wrap; word-break: break-all; color: #b6f;
    }
    #fmg-cctv-panel .cmdwrap { display: none; }
    #fmg-cctv-panel .status {
      margin-top: 8px; padding: 6px 8px; background: #0d47a1;
      border-radius: 4px; font-size: 12px; display: none;
    }
    #fmg-cctv-panel .bar {
      height: 6px; background: #333; border-radius: 3px; margin-top: 6px; overflow: hidden;
    }
    #fmg-cctv-panel .bar > i { display: block; height: 100%; width: 0;
      background: #4caf50; transition: width .2s; }
    #fmg-cctv-panel .toast-host { position: fixed; left: 50%; top: 20px;
      transform: translateX(-50%); z-index: 9999999; }
    #fmg-cctv-panel .toast {
      background: #4caf50; color: #fff; padding: 6px 14px;
      border-radius: 4px; font-size: 13px; margin-bottom: 6px;
    }
    #fmg-cctv-panel .toast.err { background: #c62828; }
  `);

  const panel = document.createElement('div');
  panel.id = 'fmg-cctv-panel';
  panel.innerHTML = `
    <button class="close" title="关闭">×</button>
    <h3>📺 央视频下载助手</h3>
    <div class="meta">正在解析...</div>
    <div class="streams"></div>
    <div class="status"></div>
    <div class="bar"><i></i></div>
    <div class="cmdwrap">
      <div style="margin-top:8px; color:#ffeb3b">📋 PowerShell 一键命令（粘到 PowerShell 7+ 运行）：</div>
      <pre class="cmd"></pre>
      <button class="copy-cmd">复制命令</button>
      <button class="copy-m3u8">复制 m3u8 URL</button>
      <button class="dl-m3u8">下载 m3u8 文件</button>
      <button class="dl-ps1 ps1">下载一键脚本(.ps1)</button>
    </div>
  `;
  document.body.appendChild(panel);

  panel.querySelector('.close').onclick = () => panel.remove();
  const metaEl = panel.querySelector('.meta');
  const streamsEl = panel.querySelector('.streams');
  const cmdWrap = panel.querySelector('.cmdwrap');
  const cmdPre = panel.querySelector('.cmd');
  const statusEl = panel.querySelector('.status');
  const barEl = panel.querySelector('.bar > i');
  const toastHost = document.createElement('div');
  toastHost.className = 'toast-host';
  document.body.appendChild(toastHost);

  function toast(msg, ok = true) {
    const t = document.createElement('div');
    t.className = 'toast' + (ok ? '' : ' err');
    t.textContent = msg;
    toastHost.appendChild(t);
    setTimeout(() => t.remove(), 2600);
  }
  function setStatus(msg) {
    statusEl.style.display = 'block';
    statusEl.textContent = msg;
  }
  function setProgress(ratio) {
    barEl.style.width = Math.max(0, Math.min(1, ratio)) * 100 + '%';
  }

  function downloadBlob(arrayBuffer, filename) {
    try {
      const blob = new Blob([arrayBuffer]);
      const a = document.createElement('a');
      a.href = URL.createObjectURL(blob);
      a.download = filename;
      document.body.appendChild(a);
      a.click();
      a.remove();
      setTimeout(() => URL.revokeObjectURL(a.href), 5000);
      toast('已下载: ' + filename);
    } catch (e) {
      toast('下载失败: ' + e.message, false);
    }
  }

  // ===== 8. 主流程 ============================================================
  (async () => {
    const guid = getGuid();
    if (!guid) {
      metaEl.textContent = '❌ 未检测到视频 guid（页面结构可能已更新）';
      return;
    }
    metaEl.innerHTML = `guid: <code>${guid.slice(0, 8)}…</code> · 加载中...`;

    let info;
    try {
      info = await fetchInfo(guid);
    } catch (e) {
      metaEl.innerHTML = `❌ 视频信息接口失败: ${e.message}`;
      return;
    }
    const title = (info.title || 'video').trim();
    const dur = parseFloat((info.video && info.video.totalLength) || 0);
    const fmtDur =
      dur > 0
        ? `${Math.floor(dur / 3600)
            .toString()
            .padStart(2, '0')}:${Math.floor((dur % 3600) / 60)
            .toString()
            .padStart(2, '0')}:${Math.floor(dur % 60)
            .toString()
            .padStart(2, '0')}`
        : '??:??:??';
    metaEl.innerHTML = `<b>${title}</b><br>时长 ${fmtDur} · guid <code>${guid.slice(
      0,
      8
    )}…</code>`;

    const streams = await probeStreams(info);
    if (!streams) {
      metaEl.innerHTML += '<br>❌ hls_url 解析失败';
      return;
    }
    streamsEl.innerHTML = '';
    let chosen = null;
    streams.forEach((s) => {
      const row = document.createElement('div');
      row.className = 'row';
      let badge = '';
      if (!s.ok) {
        badge = `<span class="badge err">${s.reason || '失败'}</span>`;
      } else if (s.real) {
        badge = `<span class="badge real">真</span>`;
      } else {
        badge = `<span class="badge fake">诱饵/别名</span>`;
      }
      row.innerHTML = `
        <div>
          <span class="kbps">${s.label}</span>
          <span class="seg">${s.res}${
        s.ok ? ` · ${s.segments} 段 · 段0 ${(s.seg0Bytes / 1024).toFixed(0)}KB` : ''
      }</span>
          ${badge}
        </div>
        ${
          s.ok
            ? `
        <div class="btns">
          ${s.real ? `<button class="dlmp4" data-act="mp4" data-kbps="${s.kbps}">⬇ 直接下载 MP4</button>` : ''}
          ${s.real ? `<button class="ps1" data-act="ps1" data-kbps="${s.kbps}">下载一键脚本</button>` : ''}
          <button data-act="m3u8" data-url="${s.url}">复制 m3u8</button>
          ${
            s.real
              ? `<button data-act="cmd" data-kbps="${s.kbps}">复制 ffmpeg 命令</button>`
              : ''
          }
          <button data-act="dl" data-url="${s.url}" data-kbps="${s.kbps}">下载 m3u8</button>
        </div>`
            : ''
        }
      `;
      streamsEl.appendChild(row);
      if (s.ok && s.real && !chosen) chosen = s;
    });

    if (!chosen) {
      metaEl.innerHTML += '<br>⚠️ 未找到真原始流档位，所有档都是诱饵/不可用';
      return;
    }
    metaEl.innerHTML += `<br>✅ 推荐: <b>${chosen.label}</b> (${chosen.res})`;

    // 命令区按钮事件
    panel.querySelector('.copy-cmd').onclick = () => {
      try {
        GM_setClipboard(cmdPre.textContent);
        toast('命令已复制');
      } catch (e) {
        toast('复制失败: ' + e.message, false);
      }
    };
    panel.querySelector('.copy-m3u8').onclick = () => {
      try {
        GM_setClipboard(chosen.url);
        toast('m3u8 URL 已复制');
      } catch (e) {
        toast('复制失败: ' + e.message, false);
      }
    };
    panel.querySelector('.dl-m3u8').onclick = async () => {
      try {
        const r = await gmFetch(chosen.url, {
          responseType: 'arraybuffer',
          headers: BASE_HEADERS,
        });
        downloadBlob(
          r.response,
          `${title.replace(/[\\/:*?"<>|]/g, '_')}_${chosen.kbps}.m3u8`
        );
      } catch (e) {
        toast('下载失败: ' + e.message, false);
      }
    };
    panel.querySelector('.dl-ps1').onclick = () => {
      try {
        downloadPs1(chosen, title);
        toast('一键脚本已下载，右键「使用 PowerShell 运行」');
      } catch (e) {
        toast('脚本下载失败: ' + e.message, false);
      }
    };

    // 行按钮事件
    streamsEl.querySelectorAll('button').forEach((btn) => {
      btn.onclick = async () => {
        const act = btn.dataset.act;
        const url = btn.dataset.url;
        const kbps = parseInt(btn.dataset.kbps, 10);
        const s = streams.find((x) => x.kbps === kbps);
        if (act === 'm3u8') {
          try {
            GM_setClipboard(url);
            toast('m3u8 URL 已复制');
          } catch (e) {
            toast('复制失败: ' + e.message, false);
          }
        } else if (act === 'cmd') {
          const cmd = buildFfCmd(s, title);
          try {
            GM_setClipboard(cmd);
            toast('ffmpeg 命令已复制');
          } catch (e) {
            toast('复制失败: ' + e.message, false);
          }
          cmdPre.textContent = cmd;
          cmdWrap.style.display = 'block';
        } else if (act === 'dl') {
          try {
            const r = await gmFetch(url, {
              responseType: 'arraybuffer',
              headers: BASE_HEADERS,
            });
            downloadBlob(
              r.response,
              `${title.replace(/[\\/:*?"<>|]/g, '_')}_${kbps}.m3u8`
            );
          } catch (e) {
            toast('下载失败: ' + e.message, false);
          }
        } else if (act === 'ps1') {
          try {
            downloadPs1(s, title);
            toast('一键脚本已下载');
          } catch (e) {
            toast('脚本下载失败: ' + e.message, false);
          }
        } else if (act === 'mp4') {
          btn.disabled = true;
          setProgress(0);
          try {
            await downloadMp4(s, title, setStatus, setProgress);
            toast('MP4 下载完成');
          } catch (e) {
            setStatus('❌ 浏览器内下载失败：' + e.message);
            // 自动回退：展开命令区，提供一键脚本和 ffmpeg 命令
            const cmd = buildFfCmd(s, title);
            cmdPre.textContent = cmd;
            cmdWrap.style.display = 'block';
            toast('已自动为你生成 ffmpeg 命令与一键脚本（推荐下载 .ps1 双击运行）', false);
          } finally {
            btn.disabled = false;
            setTimeout(() => {
              statusEl.style.display = 'none';
              setProgress(0);
            }, 6000);
          }
        }
      };
    });
  })();
}

// ===== 公众号验证码解锁弹窗 ==================================================
(function showVerifyGate() {
  'use strict';

  // 已通过则直接启动（同一浏览器无需重复验证）
  try {
    if (localStorage.getItem(VERIFY_STORAGE_KEY) === '1') {
      initCctvDownloader();
      return;
    }
  } catch (e) { /* ignore */ }

  const overlay = document.createElement('div');
  overlay.id = 'fmg-verify-overlay';
  overlay.innerHTML = `
    <div id="fmg-verify-box">
      <div id="fmg-verify-title">欢迎使用大冯老师的央视频下载助手</div>
      <img id="fmg-verify-qr" src="${QR_CODE_DATA_URI}" alt="公众号二维码" />
      <div id="fmg-verify-tip">
        请使用微信扫描上方二维码，关注公众号<br/>
        <strong>「数智化教学大冯老师」</strong><br/>
        关注后发送 <span class="fmg-keyword">央下载</span>，即可收到验证码。
      </div>
      <input id="fmg-verify-input" type="text" maxlength="24" placeholder="输入公众号回复的验证码" autocomplete="off" />
      <div id="fmg-verify-error">验证码错误，请检查后重新输入</div>
      <div id="fmg-verify-net">⏳ 正在连接验证服务器…</div>
      <div id="fmg-verify-btns">
        <button id="fmg-verify-submit">确认解锁</button>
        <button id="fmg-verify-close">取消</button>
      </div>
    </div>
  `;
  document.body.appendChild(overlay);

  GM_addStyle(`
    #fmg-verify-overlay {
      position: fixed;
      inset: 0;
      z-index: 999999;
      background: rgba(0,0,0,0.72);
      display: flex;
      align-items: center;
      justify-content: center;
      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang SC", "Microsoft YaHei", sans-serif;
    }
    #fmg-verify-box {
      width: 360px;
      max-width: 92vw;
      background: #fff;
      border-radius: 14px;
      padding: 26px 22px 22px;
      box-shadow: 0 20px 60px rgba(0,0,0,0.35);
      text-align: center;
      animation: fmg-verify-pop 0.25s ease-out;
    }
    @keyframes fmg-verify-pop {
      from { transform: scale(0.92); opacity: 0; }
      to { transform: scale(1); opacity: 1; }
    }
    #fmg-verify-title {
      font-size: 18px;
      font-weight: 700;
      color: #111;
      margin-bottom: 16px;
    }
    #fmg-verify-qr {
      width: 200px;
      height: 200px;
      object-fit: contain;
      border: 1px solid #e5e7eb;
      border-radius: 10px;
      margin-bottom: 14px;
    }
    #fmg-verify-tip {
      font-size: 14px;
      color: #4b5563;
      line-height: 1.7;
      margin-bottom: 16px;
    }
    #fmg-verify-tip .fmg-keyword {
      display: inline-block;
      background: #10b981;
      color: #fff;
      padding: 1px 8px;
      border-radius: 4px;
      font-weight: 600;
      margin: 0 2px;
    }
    #fmg-verify-input {
      width: 100%;
      box-sizing: border-box;
      padding: 11px 12px;
      font-size: 15px;
      border: 1px solid #d1d5db;
      border-radius: 8px;
      outline: none;
      margin-bottom: 6px;
      text-align: center;
      letter-spacing: 1px;
    }
    #fmg-verify-input:focus {
      border-color: #10b981;
      box-shadow: 0 0 0 3px rgba(16,185,129,0.15);
    }
    #fmg-verify-error {
      color: #ef4444;
      font-size: 13px;
      height: 18px;
      margin-bottom: 10px;
      visibility: hidden;
    }
    #fmg-verify-net {
      font-size: 12px;
      color: #6b7280;
      height: 16px;
      line-height: 16px;
      margin-bottom: 10px;
    }
    #fmg-verify-net.ok { color: #10b981; }
    #fmg-verify-net.warn { color: #f59e0b; }
    #fmg-verify-net.bad { color: #ef4444; }
    #fmg-verify-btns {
      display: flex;
      gap: 10px;
    }
    #fmg-verify-btns button:disabled {
      opacity: 0.6;
      cursor: not-allowed;
    }
    #fmg-verify-btns button {
      flex: 1;
      padding: 11px 0;
      border: none;
      border-radius: 8px;
      font-size: 15px;
      cursor: pointer;
      transition: opacity 0.15s;
    }
    #fmg-verify-btns button:hover { opacity: 0.9; }
    #fmg-verify-submit {
      background: #10b981;
      color: #fff;
      font-weight: 600;
    }
    #fmg-verify-close {
      background: #f3f4f6;
      color: #374151;
    }
  `);

  const input = overlay.querySelector('#fmg-verify-input');
  const error = overlay.querySelector('#fmg-verify-error');
  const net = overlay.querySelector('#fmg-verify-net');
  const submit = overlay.querySelector('#fmg-verify-submit');

  function setNet(text, cls) {
    net.textContent = text;
    net.className = cls || '';
  }
  function showErr(msg) {
    error.textContent = msg;
    error.style.visibility = 'visible';
  }

  function closeGate(abort) {
    overlay.remove();
    if (abort) {
      console.warn('[大冯老师的央视频下载助手] 验证未通过，脚本未启动。');
    }
  }

  // 弹窗打开即预热：先把验证码从 COS 拉下来，用户点确认时几乎零等待
  let warm = null;
  loadRemoteCodes().then((res) => {
    warm = res;
    if (res.source === 'remote') setNet('✅ 验证服务器已就绪', 'ok');
    else if (res.source === 'cache') setNet('⚠️ 联网失败，将用上次缓存的验证码校验', 'warn');
    else if (res.source === 'offline') setNet('⚠️ 联网失败，将用应急离线码校验', 'warn');
    else setNet('❌ 验证服务器连接失败，请检查网络后重试', 'bad');
  });

  async function doVerify() {
    const val = normCode(input.value);
    if (!val) return;
    submit.disabled = true;
    const oldText = submit.textContent;
    submit.textContent = '校验中…';
    error.style.visibility = 'hidden';
    try {
      const res = warm && warm.codes.length ? warm : await loadRemoteCodes();
      warm = res;
      if (!res.codes.length) {
        setNet('❌ 验证服务器连接失败，请检查网络后重试', 'bad');
        return;
      }
      if (res.codes.indexOf(val) >= 0) {
        try { localStorage.setItem(VERIFY_STORAGE_KEY, '1'); } catch (e) { /* ignore */ }
        closeGate(false);
        initCctvDownloader();
      } else {
        showErr('验证码错误，请检查后重新输入');
        input.select();
      }
    } finally {
      submit.disabled = false;
      submit.textContent = oldText;
    }
  }

  submit.addEventListener('click', doVerify);
  input.addEventListener('keydown', (e) => { if (e.key === 'Enter') doVerify(); });
  overlay.querySelector('#fmg-verify-close').addEventListener('click', () => closeGate(true));
  overlay.addEventListener('click', (e) => { if (e.target === overlay) closeGate(true); });
})();
